import { readFile, writeFile } from 'node:fs/promises';
import path from 'node:path';
import { routeMetadata } from '../src/lib/route-metadata.ts';

// Opt-in preparation only. The normal GitHub Pages build does not emit _headers.
const directory = process.argv[2] ?? 'dist';
const html = await readFile(path.join(directory, 'index.html'), 'utf8');
const policy = html.match(/http-equiv="Content-Security-Policy" content="([^"]+)"/)?.[1];
if (!policy) throw new Error('Run the production build before preparing headers.');
const lines = [
  '# Generated by scripts/prepare-cloudflare.mjs; only Cloudflare Pages interprets this file.',
  '/*',
  `  Content-Security-Policy: ${policy}; frame-ancestors 'none'`,
  '  Strict-Transport-Security: max-age=31536000',
  '  X-Content-Type-Options: nosniff',
  '  X-Frame-Options: DENY',
  '  Referrer-Policy: strict-origin-when-cross-origin',
  '  Permissions-Policy: camera=(), microphone=(), geolocation=(), payment=(), usb=()',
];
// Exact HTML paths avoid merging conflicting max-age values with asset rules.
const entries = new Set(['/index.html', '/404.html']);
for (const { url } of Object.values(routeMetadata)) {
  const pathname = new URL(url).pathname;
  entries.add(pathname);
  entries.add(`${pathname}index.html`);
}
for (const entry of entries) lines.push('', entry, '  Cache-Control: public, max-age=0, must-revalidate');
for (const prefix of ['/assets/*', '/images/optimized/*', '/fonts/subsets/*']) {
  lines.push('', prefix, '  Cache-Control: public, max-age=31536000, immutable');
}
if (lines.some(line => line.length > 2000)) throw new Error('Cloudflare header line exceeds 2,000 characters.');
await writeFile(path.join(directory, '_headers'), lines.join('\n') + '\n');
console.log('Prepared Cloudflare headers. No hosting or DNS changes were made.');
